gsap.registerPlugin(ScrollTrigger);

//hendzzz

/* =========================
   HELPER
========================= */
const get = (el, key, def) => {
  const val = el.dataset[key];
  if (val === undefined) return def;
  if (val === "true") return true;
  if (val === "false") return false;
  if (!isNaN(val)) return parseFloat(val);
  return val;
};

/* =========================
   TARGET RESOLVER
========================= */
const resolveTarget = (el) => {
  const t = el.dataset.target;
  if (!t) return el;
  if (t === "self") return el;
  if (t === "parent") return el.parentElement;
  return el.querySelector(t) || el;
};

/* =========================
   TRIGGER RESOLVER
========================= */
const resolveTrigger = (el) => {
  const t = el.dataset.trigger;
  if (!t || t === "false") return el;
  if (t === "parent") return el.parentElement;
  return document.querySelector(t) || el;
};

/* =========================
   SCROLLTRIGGER CONFIG
========================= */
const commonST = (el) => {
  const scrub = get(el, "scrub", false);
  const reverse = get(el, "reverse", false);
  const triggerEl = resolveTrigger(el);

  if (scrub) {
    return {
      trigger: triggerEl,
      start: get(el, "start", "top 85%"),
      end: get(el, "end", "bottom top"),
      scrub: scrub
    };
  }

  return {
    trigger: triggerEl,
    start: get(el, "start", "top 85%"),
    end: get(el, "end", "bottom top"),
    onEnter: (self) => self.animation.play(),
    onEnterBack: (self) => self.animation.play(),
    onLeave: (self) => reverse && self.animation.reverse(),
    onLeaveBack: (self) => reverse && self.animation.reverse()
  };
};

/* =========================
   APPLY
========================= */
const apply = (el, from, to) => {
  const target = resolveTarget(el);
  const scrub = get(el, "scrub", false);

  // SCRUB MODE
  if (scrub) {
    return gsap.fromTo(target, from, {
      ...to,
      ease: "none",
      immediateRender: false,
      scrollTrigger: commonST(el),
      onStart: () => {
        target.style.visibility = "visible";
        target.style.opacity = "1";
      }
    });
  }

  // NORMAL MODE
  gsap.set(target, {
    ...from,
    opacity: 1,
    visibility: "visible"
  });

  const tween = gsap.to(target, {
    ...to,
    opacity: 1,
    ease: "power2.inOut",
    duration: get(el, "duration", 1.2),
    delay: get(el, "delay", 0),
    paused: true
  });

  ScrollTrigger.create({
    ...commonST(el),
    animation: tween
  });

  return tween;
};

/* =========================
   PRESETS
========================= */
const presets = {

  // ======================
  // MASK BASIC
  // ======================
  "mask-left": (el) => apply(el,
    { clipPath: "inset(0% 0% 0% 100%)" },
    { clipPath: "inset(0% 0% 0% 0%)" }
  ),

  "mask-right": (el) => apply(el,
    { clipPath: "inset(0% 100% 0% 0%)" },
    { clipPath: "inset(0% 0% 0% 0%)" }
  ),

  "mask-top": (el) => apply(el,
    { clipPath: "inset(100% 0% 0% 0%)" },
    { clipPath: "inset(0% 0% 0% 0%)" }
  ),

  "mask-bottom": (el) => apply(el,
    { clipPath: "inset(0% 0% 100% 0%)" },
    { clipPath: "inset(0% 0% 0% 0%)" }
  ),

  // ======================
  // DOUBLE SIDE (FIXED 🔥)
  // ======================
  "mask-left-right": (el) => apply(el,
    { scaleX: 0, transformOrigin: "center" },
    { scaleX: 1 }
  ),

  "mask-top-bottom": (el) => apply(el,
    { scaleY: 0, transformOrigin: "center" },
    { scaleY: 1 }
  ),

  // ======================
  // CENTER
  // ======================
  "mask-center": (el) => apply(el,
    { clipPath: "inset(50% 50% 50% 50%)" },
    { clipPath: "inset(0% 0% 0% 0%)" }
  ),

  "mask-center-horizontal": (el) => apply(el,
    { clipPath: "inset(0% 50% 0% 50%)" },
    { clipPath: "inset(0% 0% 0% 0%)" }
  ),

  "mask-center-vertical": (el) => apply(el,
    { clipPath: "inset(50% 0% 50% 0%)" },
    { clipPath: "inset(0% 0% 0% 0%)" }
  ),

  // ======================
  // CIRCLE
  // ======================
  "circle-center": (el) => apply(el,
    { clipPath: "circle(0% at 50% 50%)" },
    { clipPath: "circle(100% at 50% 50%)" }
  ),

  // ======================
  // SLIDE
  // ======================
  "slide-left": (el) => apply(el,
    { x: 120, opacity: 0 },
    { x: 0, opacity: 1 }
  ),

  "slide-right": (el) => apply(el,
    { x: -120, opacity: 0 },
    { x: 0, opacity: 1 }
  ),

  "slide-up": (el) => apply(el,
    { y: 120, opacity: 0 },
    { y: 0, opacity: 1 }
  ),

  "slide-down": (el) => apply(el,
    { y: -120, opacity: 0 },
    { y: 0, opacity: 1 }
  ),

  // ======================
  // DIAGONAL
  // ======================
  "diagonal-bl": (el) => apply(el,
    { x: -150, y: 150, opacity: 0 },
    { x: 0, y: 0, opacity: 1 }
  ),

  "diagonal-br": (el) => apply(el,
    { x: 150, y: 150, opacity: 0 },
    { x: 0, y: 0, opacity: 1 }
  ),

  "diagonal-tl": (el) => apply(el,
    { x: -150, y: -150, opacity: 0 },
    { x: 0, y: 0, opacity: 1 }
  ),

  "diagonal-tr": (el) => apply(el,
    { x: 150, y: -150, opacity: 0 },
    { x: 0, y: 0, opacity: 1 }
  ),

  // ======================
  // EFFECT
  // ======================
  "zoom-in": (el) => apply(el,
    { scale: 1.5, opacity: 0 },
    { scale: 1, opacity: 1 }
  ),

  "zoom-out": (el) => apply(el,
    { scale: 0.5, opacity: 0 },
    { scale: 1, opacity: 1 }
  ),

  "rotate-in": (el) => apply(el,
    { rotate: -180, opacity: 0 },
    { rotate: 0, opacity: 1 }
  ),

  "flip-x": (el) => apply(el,
    { rotateX: 90, opacity: 0 },
    { rotateX: 0, opacity: 1 }
  ),

  "blur-in": (el) => apply(el,
    { filter: "blur(20px)", opacity: 0 },
    { filter: "blur(0px)", opacity: 1 }
  ),

  "pop-in": (el) => apply(el,
    { scale: 0, opacity: 0 },
    { scale: 1, opacity: 1 }
  )
};

/* =========================
   INIT
========================= */
window.addEventListener("load", () => {
  document.querySelectorAll("[data-reveal]").forEach(el => {
    const type = el.dataset.reveal;
    if (presets[type]) presets[type](el);
  });
});